<script setup lang="ts">
import { uiText } from '@/i18n'

import ReadingSelection from '@/components/ReadingSelection.vue'
import { ref,onMounted,onBeforeUnmount,computed,watch } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router'
import { request,api,fetchBlob } from '@/api/client'
import { researchApi } from '@/api/research'
import { authStore } from '@/stores/auth'
interface Document {id:string;title:string;format:string;createdAt:string}
interface Passage {id:string;documentId:string;positionNumber:number;locator:string;body:string;revision:number}
const docs=ref<Document[]>([]),parts=ref<Passage[]>([]),selected=ref(''),index=ref(0),busy=ref(false),error=ref(''),route=useRoute(),router=useRouter(),controller=new AbortController()
const recognize=ref(true),message=ref(''),proof=ref(false),draft=ref(''),imageUrl=ref(''),imageBusy=ref(false);let imageEpoch=0
const current=computed(()=>parts.value[index.value]);let epoch=0
const dirty=computed(()=>proof.value&&draft.value!==current.value?.body)
function discard(){return !authStore.state.user||!dirty.value||confirm(uiText('校对内容尚未保存，确定放弃修改吗？'))}
function changePart(next:number){if(!busy.value&&discard())index.value=next}
function warnUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(discard);onBeforeRouteUpdate(discard)
onMounted(()=>window.addEventListener('beforeunload',warnUnload))
onBeforeUnmount(()=>window.removeEventListener('beforeunload',warnUnload))
async function load(){docs.value=await request<Document[]>('/research/documents',{signal:controller.signal})}
async function open(id:string,passage?:string){if(!discard())return;const version=++epoch;selected.value=id;parts.value=[];index.value=0;error.value='';try{const result=await request<Passage[]>('/research/documents/'+id,{signal:controller.signal});if(version===epoch&&!controller.signal.aborted){parts.value=result;index.value=Math.max(0,result.findIndex(p=>p.id===passage))}}catch(e){if(version===epoch&&!controller.signal.aborted)error.value=(e as Error).message}}
async function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||busy.value)return;busy.value=true;error.value='';try{const form=new FormData();form.set('file',file);form.set('ocr',String(recognize.value));form.set('requestId',crypto.randomUUID());await request('/workspace-jobs/documents',{method:'POST',body:form,signal:controller.signal});message.value='已加入后台任务。可离开页面，完成后从任务中心打开。'}catch(e){if(!controller.signal.aborted)error.value=(e as Error).message}finally{busy.value=false}}
async function proofread(){if(!current.value||!discard())return;proof.value=!proof.value;draft.value=current.value.body;if(!proof.value)return;const page=Number(current.value.locator.match(/第 (\d+) 页/)?.[1]);if(!page)return;const version=++imageEpoch;imageBusy.value=true;try{const blob=await fetchBlob(`/research/documents/${selected.value}/pages/${page}`);if(version===imageEpoch&&!controller.signal.aborted){if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);imageUrl.value=URL.createObjectURL(blob)}}catch(e){if(version===imageEpoch)error.value=(e as Error).message}finally{if(version===imageEpoch)imageBusy.value=false}}
async function correct(){if(!current.value||busy.value)return;busy.value=true;error.value='';try{const p=await request<Passage>('/research/documents/passages/'+current.value.id,{method:'PATCH',body:JSON.stringify({body:draft.value,revision:current.value.revision})});parts.value[index.value]=p;proof.value=false;message.value='校对已保存，搜索将使用修正后的内容'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch(()=>current.value?.id,()=>{imageEpoch++;proof.value=false;imageBusy.value=false;if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);imageUrl.value=''})
async function capture(){if(!current.value||busy.value)return;busy.value=true;try{const n=await researchApi.capture('DOCUMENT',current.value.id);if(!controller.signal.aborted)void router.push('/app/notes/'+n.id+'/edit')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(){if(!selected.value||!confirm(uiText('移除这份文档的搜索内容？已有笔记副本会保留。')))return;busy.value=true;try{await request('/research/documents/'+selected.value,{method:'DELETE'});epoch++;selected.value='';parts.value=[];await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function download(){try{await api.download('/research/documents/'+selected.value+'/original',docs.value.find(d=>d.id===selected.value)?.title||'document')}catch(e){error.value=(e as Error).message}}
onMounted(async()=>{try{await load();if(route.query.passage){const p=await request<Passage>('/research/documents/passages/'+encodeURIComponent(String(route.query.passage)),{signal:controller.signal});await open(p.documentId,p.id)}else if(route.query.document)await open(String(route.query.document))}catch(e){if(!controller.signal.aborted)error.value=(e as Error).message}})
onBeforeUnmount(()=>{epoch++;imageEpoch++;controller.abort();if(imageUrl.value)URL.revokeObjectURL(imageUrl.value)})
</script>
<template><div><header class="research-section-title"><div><h2>{{ uiText('把资料读进知识库') }}</h2><p class="research-hint">{{ uiText('PDF / Word 导入后可搜索、摘录和制作复习卡。最多 10 MB、300 页；一次最多识别 60 个扫描页。') }}</p></div><label v-if="authStore.has('note:write')" class="button button--dark">{{busy?uiText('正在处理…'):uiText('导入文档')}}<input type="file" accept=".pdf,.docx" :disabled="busy" @change="upload" class="document-file-input" /></label></header><p><label><input v-model="recognize" type="checkbox" :disabled="busy"/>{{ uiText('自动识别扫描页（本地中英文 OCR）') }}</label> · <RouterLink to="/app/research?tab=tasks">{{ uiText('任务与同步 →') }}</RouterLink> · <button class="table-action" @click="load().catch(e=>error=e.message)">{{ uiText('刷新文档') }}</button></p><p v-if="message" role="status">{{message}}</p><p v-if="error" role="alert" class="form-error">{{ uiText(error) }}</p><div class="document-reader"><aside><p v-if="!docs.length" class="research-hint">{{ uiText('导入后的文档会显示在这里。') }}</p><button v-for="d in docs" :key="d.id" :class="{active:selected===d.id}" :disabled="busy" @click="open(d.id)"><small>{{d.format}}</small>{{d.title}}</button></aside><section v-if="current"><header class="research-section-title"><h3>{{current.locator}}</h3><div class="research-actions"><button class="button button--ghost" @click="download">{{ uiText('下载原文') }}</button><button v-if="authStore.has('note:write')" class="button button--ghost" :disabled="busy" @click="capture">{{ uiText('本段存为笔记') }}</button></div></header><ReadingSelection :key="current.id" kind="DOCUMENT" :source-id="current.id"><p class="document-text">{{current.body}}</p></ReadingSelection><button v-if="authStore.has('note:write')" class="button" :disabled="busy" @click="proofread">{{proof?uiText('关闭校对'):uiText('对照原页并校对')}}</button><section v-if="proof" class="proofreader"><p v-if="imageBusy">{{ uiText('正在加载原页…') }}</p><img v-if="imageUrl" :src="imageUrl" :alt="uiText('原 PDF 页面，用于核对识别文字')"/><div><label>{{ uiText('校对当前片段') }}<textarea v-model="draft" class="field-input" rows="18" maxlength="4000"/></label><button class="button button--dark" :disabled="busy||!draft.trim()" @click="correct">{{ uiText('保存校对') }}</button></div></section><nav class="research-pagination"><button class="button" :disabled="busy||index===0" @click="changePart(index-1)">{{ uiText('上一段') }}</button><select :value="index" :disabled="busy" @change="changePart(Number(($event.target as HTMLSelectElement).value));($event.target as HTMLSelectElement).value=String(index)" :aria-label="uiText('跳转到原文位置')" class="field-input"><option v-for="(p,i) in parts" :key="p.id" :value="i">{{p.locator}}</option></select><button class="button" :disabled="busy||index===parts.length-1" @click="changePart(index+1)">{{ uiText('下一段') }}</button></nav><div class="research-actions"><RouterLink :to="{path:'/app/research',query:{tab:'search',type:'DOCUMENT',source:current.id}}">{{ uiText('引用这一段提问 →') }}</RouterLink><button v-if="authStore.has('note:write')" class="table-action" :disabled="busy" @click="remove">{{ uiText('移除文档') }}</button></div><p class="research-hint">{{ uiText('PDF 按原页码定位；Word 按段落定位。扫描页自动进行本地 OCR；复杂排版和识别结果请对照原页核实。校对只更新提取文字，保留原文件。') }}</p></section><section v-else class="research-empty">{{ uiText('选择文档，开始阅读。') }}</section></div></div></template>
<style scoped>.proofreader{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:20px 0}.proofreader img{max-width:100%;border:1px solid var(--line)}.proofreader textarea{margin:12px 0}.proofreader>div{min-width:0}.document-reader{display:grid;grid-template-columns:240px minmax(0,1fr);gap:36px;margin-top:24px}.document-reader aside{border-right:1px solid var(--line);padding-right:20px}.document-reader aside button{display:block;width:100%;text-align:left;padding:14px;background:transparent;border:0;border-left:2px solid transparent;color:var(--ink);font:inherit;cursor:pointer;overflow-wrap:anywhere}.document-reader aside small{display:block;color:var(--muted);margin-bottom:6px}.document-reader aside button.active{border-color:var(--green);background:var(--surface-soft)}.document-text{white-space:pre-wrap;line-height:2;font-size:16px;overflow-wrap:anywhere;min-height:260px}.document-file-input{position:absolute;width:1px;height:1px;opacity:0}.research-pagination select{max-width:250px}.research-actions{flex-wrap:wrap}@media(max-width:760px){.document-reader{grid-template-columns:1fr}}</style>
